nextflow_process {

    name "Test Process SAMTOOLS_MARKDUP"
    script "../main.nf"
    process "SAMTOOLS_MARKDUP"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "samtools"
    tag "samtools/fixmate"
    tag "samtools/sort"
    tag "samtools/markdup"

    test("sarscov2 - bam") {
        setup {
            run("SAMTOOLS_FIXMATE") {
                script "../../fixmate/main.nf"
                process {
                    """
                    input[0] = [
                        [ id:'test' ],
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.bam', checkIfExists: true),
                    ]
                    input[1] = [
                        [ id:'fasta' ],
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true),
                    ]
                    """
                }
            }
            run("SAMTOOLS_SORT") {
                script "../../sort/main.nf"
                process {
                    """
                    input[0] = SAMTOOLS_FIXMATE.out.bam
                    input[1] = [
                        [ id:'fasta' ],
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true),
                    ]
                    input[2] = ''
                    """
                }
            }
        }
        when {
            process {
                """
                input[0] = SAMTOOLS_SORT.out.bam
                input[1] = [
                    [ id:'fasta' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true),
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("sarscov2 - bam - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.bam', checkIfExists: true),
                ]
                input[1] = [
                    [ id:'fasta' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true),
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

process {
    withName: SAMTOOLS_FIXMATE {
        ext.prefix = { "${meta.id}.fixmate" }
    }
    withName: SAMTOOLS_SORT {
        ext.prefix = { "${meta.id}.sorted" }
    }
    withName: SAMTOOLS_MARKDUP {
        ext.prefix = { "${meta.id}.markdup" }
    }
}
